    // Process each polygon in the input
    for (const auto& polygon : polygon_coords) {
        if (polygon.size() < 6) {
            continue; // Need at least 3 points for a polygon (3D: x,y,z for each point)
        }

        // Create a 2D point vector for the polygon vertices
        std::vector<Kernel::Point_2> points_2d;

        // Project each 3D point to the plane to get 2D coordinates
        for (size_t i = 0; i < polygon.size() - 2; i += 3) {
