            Kernel::Point_2 p2d = plane.to_2d(p3d);
            points_2d.push_back(p2d);
        }

        // Insert the points as a constraint
        if (!points_2d.empty()) {
            // Create constraint as a polygon
            std::vector<Triangulation::Vertex_handle> vertices;
            for (const auto& point : points_2d) {
                // Insert each point and keep track of vertices
