                if (vh != Triangulation::Vertex_handle()) {
                    vertices.push_back(vh);
                }
            }

            // Constrain the edges of the polygon
            if (vertices.size() > 1) {
                for (size_t i = 0; i < vertices.size() - 1; ++i) {
                    triangulation.odd_even_insert_constraint(vertices[i], vertices[i+1]);
                }
                // Close the polygon
                triangulation.odd_even_insert_constraint(vertices.back(), vertices.front());
            }
        }
    }
